// ============================================================================
// 🚀 TURBO SPEED TELEMETRY & TRACKER SHIELD (DeclarativeNetRequest Engine)
// ============================================================================
const TELEMETRY_RULE_IDS = [99001, 99002, 99003, 99004, 99005];
const TELEMETRY_RULES = [
  {
    id: 99002,
    priority: 1,
    action: { type: 'block' },
    condition: {
      urlFilter: '||mcs.snssdk.com',
      resourceTypes: ['xmlhttprequest', 'ping', 'other']
    }
  },
  {
    id: 99003,
    priority: 1,
    action: { type: 'block' },
    condition: {
      urlFilter: '||toblog.ctobsnssdk.com',
      resourceTypes: ['xmlhttprequest', 'ping', 'other']
    }
  }
];

function applyTelemetryShield(enabled = true) {
  try {
    if (!chrome.declarativeNetRequest || !chrome.declarativeNetRequest.updateDynamicRules) return;
    if (enabled) {
      chrome.declarativeNetRequest.updateDynamicRules({
        removeRuleIds: TELEMETRY_RULE_IDS,
        addRules: TELEMETRY_RULES
      }).catch(() => {});
    } else {
      chrome.declarativeNetRequest.updateDynamicRules({
        removeRuleIds: TELEMETRY_RULE_IDS
      }).catch(() => {});
    }
  } catch (e) {}
}

chrome.storage.local.get(['ctb_telemetry_shield'], (res) => {
  const isEnabled = res?.ctb_telemetry_shield !== false; // Active by default
  applyTelemetryShield(isEnabled);
});

// ============================================================================
// 📥 ChannaTheBrand 1080P Unwatermarked Master Video Auto-Downloader
// ============================================================================

const ZDOLA_STORAGE_KEYS = {
  config: 'zdola_auto_download_config',
  history: 'zdola_download_history',
  // Keep the old key untouched: earlier builds also recorded DOM preview URLs
  // there, so it cannot safely suppress downloads of the raw stream.
  downloadedSet: 'zdola_unwatermarked_downloaded_urls',
  canceledSet: 'zdola_user_canceled_urls',
  downloadMediaMap: 'zdola_download_media_by_id'
};

const ZDOLA_DEFAULT_CONFIG = {
  autoDownload: true,
  notifications: true,
  subfolder: 'ChannaTheBrand_Videos',
  qualityPreference: '1080P',
  totalDownloaded: 0,
  filenamePattern: '{prompt}_{duration}'
};

let zdolaConfig = { ...ZDOLA_DEFAULT_CONFIG };
let zdolaDownloadHistory = [];
let zdolaDownloadedKeys = new Set();
let zdolaInProgressKeys = new Set();
let zdolaCanceledKeys = new Set();
let zdolaDownloadMediaById = new Map();
const zdolaCanceledDownloadIds = new Set();

async function zdolaLoadState() {
  try {
    const data = await chrome.storage.local.get([
      ZDOLA_STORAGE_KEYS.config,
      ZDOLA_STORAGE_KEYS.history,
      ZDOLA_STORAGE_KEYS.downloadedSet,
      ZDOLA_STORAGE_KEYS.canceledSet,
      ZDOLA_STORAGE_KEYS.downloadMediaMap
    ]);

    if (data[ZDOLA_STORAGE_KEYS.config]) {
      zdolaConfig = { ...ZDOLA_DEFAULT_CONFIG, ...data[ZDOLA_STORAGE_KEYS.config] };
      // Ensure folder is ChannaTheBrand_Videos
      if (!zdolaConfig.subfolder || zdolaConfig.subfolder === 'ZDola_Videos') {
        zdolaConfig.subfolder = 'ChannaTheBrand_Videos';
      }
    }
    if (Array.isArray(data[ZDOLA_STORAGE_KEYS.history])) {
      zdolaDownloadHistory = data[ZDOLA_STORAGE_KEYS.history];
    }
    if (Array.isArray(data[ZDOLA_STORAGE_KEYS.downloadedSet])) {
      zdolaDownloadedKeys = new Set(data[ZDOLA_STORAGE_KEYS.downloadedSet]);
    }
    for (const entry of zdolaDownloadHistory) {
      if (entry?.source !== 'fallback_api') continue;
      if (entry.mediaKey) zdolaDownloadedKeys.add(String(entry.mediaKey));
      if (entry.url) zdolaDownloadedKeys.add(String(entry.url));
    }
    if (Array.isArray(data[ZDOLA_STORAGE_KEYS.canceledSet])) {
      zdolaCanceledKeys = new Set(data[ZDOLA_STORAGE_KEYS.canceledSet]);
    }
    if (data[ZDOLA_STORAGE_KEYS.downloadMediaMap] && typeof data[ZDOLA_STORAGE_KEYS.downloadMediaMap] === 'object') {
      zdolaDownloadMediaById = new Map(Object.entries(data[ZDOLA_STORAGE_KEYS.downloadMediaMap]).map(([id, key]) => [Number(id), key]));
    }
    zdolaUpdateBadge();
  } catch (err) {
    console.error('[ChannaTheBrand Downloader] Failed to load state:', err);
  }
}

async function zdolaSaveState() {
  try {
    await chrome.storage.local.set({
      [ZDOLA_STORAGE_KEYS.config]: zdolaConfig,
      [ZDOLA_STORAGE_KEYS.history]: zdolaDownloadHistory.slice(0, 200),
      [ZDOLA_STORAGE_KEYS.downloadedSet]: Array.from(zdolaDownloadedKeys).slice(-500),
      [ZDOLA_STORAGE_KEYS.canceledSet]: Array.from(zdolaCanceledKeys).slice(-500),
      [ZDOLA_STORAGE_KEYS.downloadMediaMap]: Object.fromEntries(zdolaDownloadMediaById)
    });
  } catch (err) {
    console.error('[ChannaTheBrand Downloader] Failed to save state:', err);
  }
}

function zdolaUpdateBadge() {
  try {
    if (!zdolaConfig.autoDownload) {
      chrome.action.setBadgeText({ text: 'OFF' });
      chrome.action.setBadgeBackgroundColor({ color: '#6b7280' });
    } else {
      const count = zdolaDownloadHistory.length;
      chrome.action.setBadgeText({ text: count > 0 ? String(count) : 'ON' });
      chrome.action.setBadgeBackgroundColor({ color: '#7c3aed' });
    }
  } catch {}
}

function zdolaSanitizeFilename(text) {
  return String(text || '')
    .replace(/[<>:"/\\|?*\x00-\x1F]/g, '_')
    .replace(/\s+/g, '_')
    .replace(/_+/g, '_')
    .substring(0, 45)
    .trim();
}

function zdolaGenerateFilename(video) {
  const now = new Date();
  const dateStr = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
  const timeStr = `${String(now.getHours()).padStart(2, '0')}-${String(now.getMinutes()).padStart(2, '0')}-${String(now.getSeconds()).padStart(2, '0')}`;
  
  let candidatePrompt = (video?.prompt || video?.topicTitle || video?.title || '').trim();
  if (candidatePrompt.includes('Dola AI - Your everyday') || candidatePrompt === 'Dola Chat Video') {
    candidatePrompt = '';
  }
  const promptSlug = zdolaSanitizeFilename(candidatePrompt) || 'Video';
  const accountSlug = zdolaSanitizeFilename(video?.accountName || video?.account || 'Account_1');
  const durationSlug = video?.duration ? (String(video.duration).endsWith('s') ? String(video.duration) : `${video.duration}s`) : '30s';
  const resolutionSlug = video?.resolution || '1080P';
  const ratioSlug = zdolaSanitizeFilename(String(video?.ratio || video?.aspectRatio || '9x16').replace(':', 'x'));
  const indexStr = String((zdolaConfig.totalDownloaded || 0) + 1).padStart(2, '0');

  let pattern = zdolaConfig.filenamePattern || '{prompt}_{duration}';

  let formatted = pattern
    .replace(/\{prompt\}/gi, promptSlug)
    .replace(/\{account\}/gi, accountSlug)
    .replace(/\{date\}/gi, dateStr)
    .replace(/\{time\}/gi, timeStr)
    .replace(/\{duration\}/gi, durationSlug)
    .replace(/\{ratio\}/gi, ratioSlug)
    .replace(/\{resolution\}/gi, resolutionSlug)
    .replace(/\{index\}/gi, indexStr);

  formatted = zdolaSanitizeFilename(formatted);
  if (!formatted) formatted = `ChannaTheBrand_${dateStr}_${timeStr}`;

  const baseFolder = zdolaConfig.subfolder ? `${zdolaConfig.subfolder.replace(/[/\\?%*:|"<>]/g, '_')}/` : 'ChannaTheBrand_Videos/';
  return `${baseFolder}${formatted}.mp4`;
}

async function zdolaHandleAutoDownload(video, force = false) {
  if (!video || !video.url) return { ok: false, error: 'Invalid video URL' };
  if (!zdolaConfig.autoDownload && !force) return { ok: true, downloaded: false, reason: 'Auto-download is paused in settings' };

  // Never download a DOM/chat preview: Dola can serve those with a watermark.
  // extractor.js tags only the queried and decoded raw stream as fallback_api.
  if (video.source !== 'fallback_api') {
    return { ok: true, downloaded: false, reason: 'Waiting for the unwatermarked raw stream' };
  }

  const cleanUrl = String(video.url).trim();
  const mediaKey = String(video.vid || cleanUrl);

  // A user cancellation is an explicit stop signal. Keep it across service worker
  // restarts and don't let a forced/manual path silently start the same download again.
  if (zdolaCanceledKeys.has(mediaKey) || zdolaCanceledKeys.has(cleanUrl)) {
    return { ok: true, downloaded: false, reason: 'Download canceled by user; retry manually from the page' };
  }

  // Single-shot deduplication
  if (!force) {
    if (zdolaDownloadedKeys.has(mediaKey) || zdolaDownloadedKeys.has(cleanUrl)) {
      return { ok: true, downloaded: false, reason: 'Already downloaded' };
    }
    if (zdolaInProgressKeys.has(mediaKey)) {
      return { ok: true, downloaded: false, reason: 'Download already in progress' };
    }
  }

  zdolaInProgressKeys.add(mediaKey);
  zdolaDownloadedKeys.add(mediaKey);
  zdolaDownloadedKeys.add(cleanUrl);

  const filename = zdolaGenerateFilename(video);

  try {
    console.log('[ChannaTheBrand Downloader] Starting unwatermarked master download:', filename, cleanUrl);

    const downloadId = await chrome.downloads.download({
      url: cleanUrl,
      filename,
      saveAs: false,
      conflictAction: 'uniquify'
    });

    zdolaDownloadMediaById.set(downloadId, mediaKey);
    if (zdolaCanceledDownloadIds.delete(downloadId)) {
      zdolaCanceledKeys.add(mediaKey);
      zdolaCanceledKeys.add(cleanUrl);
      zdolaInProgressKeys.delete(mediaKey);
      await zdolaSaveState();
      return { ok: true, downloaded: false, reason: 'Download canceled by user' };
    }
    await zdolaSaveState();

    zdolaInProgressKeys.delete(mediaKey);
    zdolaConfig.totalDownloaded = (zdolaConfig.totalDownloaded || 0) + 1;

    const historyEntry = {
      id: `${Date.now()}_${Math.random().toString(36).substring(2, 7)}`,
      downloadId,
      mediaKey,
      url: cleanUrl,
      filename,
      prompt: video.prompt || video.topicTitle || video.title || 'ChannaTheBrand Unwatermarked Video',
      resolution: '1080P Raw (No Watermark)',
      source: video.source || 'fallback_api',
      timestamp: Date.now()
    };

    zdolaDownloadHistory.unshift(historyEntry);
    await zdolaSaveState();
    zdolaUpdateBadge();

    // Broadcast notification to popup
    chrome.runtime.sendMessage({
      type: 'AUTO_DOWNLOAD_COMPLETED',
      filename,
      downloadId
    }).catch(() => {});

    if (zdolaConfig.notifications) {
      try {
        if (!chrome.notifications || !chrome.notifications.create) return { ok: true, downloaded: true, downloadId, filename };
        chrome.notifications.create({
          type: 'basic',
          iconUrl: 'dox.png',
          title: '🎬 Video Downloaded (No Watermark)!',
          message: `${historyEntry.prompt.substring(0, 50)}...\nSaved to Downloads/${filename}`,
          priority: 1
        });
      } catch {}
    }

    return { ok: true, downloaded: true, downloadId, filename };
  } catch (err) {
    zdolaInProgressKeys.delete(mediaKey);
    zdolaDownloadedKeys.delete(mediaKey);
    zdolaDownloadedKeys.delete(cleanUrl);
    await zdolaSaveState();
    console.error('[ChannaTheBrand Downloader] Download failed:', err);
    return { ok: false, error: err.message || String(err) };
  }
}

// Chrome reports a deliberate cancel as USER_CANCELED. Persist only that outcome;
// network and server interruptions remain eligible for a later retry.
chrome.downloads.onChanged.addListener((delta) => {
  if (delta.error?.current !== 'USER_CANCELED' || typeof delta.id !== 'number') return;
  const mediaKey = zdolaDownloadMediaById.get(delta.id);
  if (!mediaKey) {
    zdolaCanceledDownloadIds.add(delta.id);
    return;
  }
  zdolaCanceledKeys.add(mediaKey);
  zdolaSaveState();
});

async function zdolaAutoInjectIntoExistingTabs() {
  try {
    const tabs = await chrome.tabs.query({
      url: [
        'https://*.dola.com/*',
        'https://*.doubao.com/*',
        'https://*.seaart.ai/*'
      ]
    });

    for (const tab of tabs) {
      if (!tab.id) continue;
      try {
        await chrome.scripting.executeScript({
          target: { tabId: tab.id },
          files: ['extractor.js'],
          world: 'MAIN'
        }).catch(() => {});
        await zdolaEnsureContentBridge(tab.id);
      } catch (err) {
        console.warn('[ChannaTheBrand Downloader] Injection failed on tab', tab.id, err);
      }
    }
  } catch (e) {
    console.warn('[ChannaTheBrand Downloader] autoInject failed:', e);
  }
}

async function zdolaEnsureContentBridge(tabId) {
  try {
    const probe = await chrome.scripting.executeScript({
      target: { tabId },
      func: () => globalThis.__HOSHIN_CONTENT_SCRIPT_READY__ === true
    });
    if (probe?.[0]?.result) return true;
  } catch {}

  try {
    await chrome.scripting.executeScript({ target: { tabId }, files: ['content.js'] });
    return true;
  } catch (err) {
    console.warn('[ChannaTheBrand Downloader] Content bridge unavailable on tab', tabId, err);
    return false;
  }
}

// Runtime messaging for Downloader
chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  if (message.type === 'RELOAD_EXTENSION') {
    chrome.runtime.reload();
    return true;
  }

  if (message.type === 'SET_TELEMETRY_SHIELD') {
    applyTelemetryShield(message.enabled);
    sendResponse({ ok: true, enabled: message.enabled });
    return true;
  }

  if (message.type === 'BROADCAST_MIRRORED_CLICK') {
    chrome.tabs.query({ url: ['*://*.dola.com/*', '*://*.doubao.com/*'] }, (tabs) => {
      tabs.forEach((tab) => {
        if (tab.id && tab.id !== sender?.tab?.id) {
          chrome.tabs.sendMessage(tab.id, {
            type: 'EXECUTE_MIRRORED_CLICK',
            targetData: message.targetData
          }).catch(() => {});
        }
      });
    });
    sendResponse({ ok: true });
    return true;
  }

  if (message.type === 'AUTO_DOWNLOAD_VIDEO') {
    zdolaHandleAutoDownload(message.video, Boolean(message.force)).then(sendResponse);
    return true;
  }

  if (message.type === 'GET_STATUS' || message.type === 'GET_DOWNLOADER_STATUS') {
    sendResponse({
      ok: true,
      config: zdolaConfig,
      history: zdolaDownloadHistory,
      totalDownloaded: zdolaConfig.totalDownloaded || 0
    });
    return false;
  }

  if (message.type === 'TOGGLE_AUTO_DOWNLOAD') {
    zdolaConfig.autoDownload = Boolean(message.enabled);
    zdolaSaveState().then(() => {
      zdolaUpdateBadge();
      sendResponse({ ok: true, autoDownload: zdolaConfig.autoDownload });
    });
    return true;
  }

  if (message.type === 'UPDATE_CONFIG' || message.type === 'UPDATE_DOWNLOADER_CONFIG') {
    zdolaConfig = { ...zdolaConfig, ...(message.config || {}) };
    zdolaSaveState().then(() => {
      zdolaUpdateBadge();
      sendResponse({ ok: true, config: zdolaConfig });
    });
    return true;
  }

  if (message.type === 'CLEAR_HISTORY' || message.type === 'CLEAR_DOWNLOAD_HISTORY') {
    zdolaDownloadHistory = [];
    zdolaSaveState().then(() => {
      zdolaUpdateBadge();
      sendResponse({ ok: true });
    });
    return true;
  }

  if (message.type === 'SHOW_DOWNLOAD_ITEM') {
    try {
      if (message.downloadId && chrome.downloads && chrome.downloads.show) {
        chrome.downloads.show(message.downloadId);
      } else if (chrome.downloads && chrome.downloads.showDefaultFolder) {
        chrome.downloads.showDefaultFolder();
      }
      // Android Kiwi has no folder UI — history entry is still saved.
      sendResponse({ ok: true });
    } catch (e) {
      sendResponse({ ok: false, error: String(e && e.message || e) });
    }
    return false;
  }

  if (message.type === 'TRIGGER_PAGE_SCAN_AND_DOWNLOAD') {
    (async () => {
      try {
        const [activeTab] = await chrome.tabs.query({ active: true, currentWindow: true });
        if (!activeTab || !activeTab.id) {
          return sendResponse({ ok: false, error: 'No active tab found' });
        }

        await chrome.scripting.executeScript({
          target: { tabId: activeTab.id },
          files: ['extractor.js'],
          world: 'MAIN'
        }).catch(() => {});

        await zdolaEnsureContentBridge(activeTab.id);

        const scanRes = await chrome.tabs.sendMessage(activeTab.id, { type: 'SCAN_AND_DOWNLOAD_ACTIVE_TAB' });
        if (scanRes?.ok && scanRes.foundCount > 0) {
          sendResponse({ ok: true, downloadedCount: scanRes.foundCount, unwatermarked: scanRes.unwatermarked, url: scanRes.url });
        } else {
          sendResponse({ ok: false, downloadedCount: 0, message: scanRes?.message || 'Unwatermarked 1080P stream not ready yet.' });
        }
      } catch (err) {
        sendResponse({ ok: false, error: err.message || String(err) });
      }
    })();
    return true;
  }

  // ⚡ 10-TAB PARALLEL FARM & BATCH ORCHESTRATOR MESSAGES
  if (message.type === 'LAUNCH_PARALLEL_FARM_BATCH') {
    launchParallelFarmBatch(message.batchIndex || 0).then(sendResponse);
    return true;
  }

  if (message.type === 'SWITCH_PARALLEL_FARM_BATCH') {
    switchParallelFarmBatch(message.batchIndex).then(sendResponse);
    return true;
  }

  if (message.type === 'GET_FARM_ASSIGNED_PROMPT') {
    const targetTabId = sender?.tab?.id || message.tabId;
    sendResponse(getFarmAssignedPrompt(targetTabId));
    return false;
  }

  if (message.type === 'CLOSE_FARM_TABS' || message.type === 'CLOSE_PARALLEL_FARM') {
    closeAllFarmTabs().then(sendResponse);
    return true;
  }

  if (message.type === 'GET_FARM_STATUS') {
    sendResponse(getFarmStatus());
    return false;
  }

  // ⚡ OPEN ACCOUNT / SWITCH ACCOUNT ON CURRENT ACTIVE TAB (The tab the user is currently using)
  if (message.action === 'open_profile_tab' || message.action === 'switch_profile' || message.type === 'SWITCH_PROFILE_ON_CURRENT_TAB') {
    (async () => {
      try {
        const storageData = await chrome.storage.local.get(['multi_profiles', 'active_profile_name']);
        const multiProfiles = storageData?.multi_profiles || {};
        const profile = multiProfiles[message.profileName];

        if (!profile || !profile.cookies) {
          return sendResponse({ success: false, error: 'Profile cookies not found' });
        }

        // Get the active tab on the current window
        const [activeTab] = await chrome.tabs.query({ active: true, currentWindow: true });
        
        if (activeTab && activeTab.id) {
          // Remove any lingering clean-session rules for this tab
          if (chrome.declarativeNetRequest && chrome.declarativeNetRequest.updateDynamicRules) {
            await chrome.declarativeNetRequest.updateDynamicRules({
              removeRuleIds: [activeTab.id]
            }).catch(() => {});
          }

          // Apply container session rule
          if (typeof applyTabSessionRule === 'function') {
            await applyTabSessionRule(activeTab.id, profile).catch(() => {});
          }

          // Inject cookies
          if (typeof setDolaCookies === 'function') {
            await setDolaCookies(profile.cookies).catch(() => {});
          }

          // If on Dola, reload once to activate account; otherwise navigate to Dola chat
          if (activeTab.url && activeTab.url.includes('dola.com')) {
            await chrome.tabs.reload(activeTab.id);
          } else {
            await chrome.tabs.update(activeTab.id, { url: 'https://www.dola.com/chat' });
          }

          await chrome.storage.local.set({ active_profile_name: message.profileName });
          sendResponse({ success: true, profileName: message.profileName, tabId: activeTab.id });
        } else {
          // Fallback if no active tab
          const newTab = await chrome.tabs.create({ url: 'about:blank', active: true });
          if (typeof applyTabSessionRule === 'function') {
            await applyTabSessionRule(newTab.id, profile).catch(() => {});
          }
          if (typeof setDolaCookies === 'function') {
            await setDolaCookies(profile.cookies).catch(() => {});
          }
          await chrome.tabs.update(newTab.id, { url: 'https://www.dola.com/chat' });
          await chrome.storage.local.set({ active_profile_name: message.profileName });
          sendResponse({ success: true, profileName: message.profileName, tabId: newTab.id });
        }
      } catch (err) {
        console.error('[ChannaTheBrand Pro] Open profile on current tab error:', err);
        sendResponse({ success: false, error: err.message || String(err) });
      }
    })();
    return true;
  }

});

// ============================================================================
// ⚡ 10-TAB PARALLEL FARM & BATCH ROTATION ORCHESTRATOR
// ============================================================================
const farmState = {
  active: false,
  currentBatchIndex: 0,
  farmTabs: [],
  tabPromptMap: new Map(),
  tabAccountMap: new Map(),
  slotsPerAccount: 1, // 1 tab per account (10 accounts = 10 tabs)
  accountsPerBatch: 10 // 10 accounts per batch
};

chrome.tabs.onRemoved.addListener((tabId) => {
  if (farmState.tabPromptMap.has(tabId)) {
    farmState.tabPromptMap.delete(tabId);
    farmState.tabAccountMap.delete(tabId);
    farmState.farmTabs = farmState.farmTabs.filter(id => id !== tabId);
    if (chrome.declarativeNetRequest && chrome.declarativeNetRequest.updateDynamicRules) {
      chrome.declarativeNetRequest.updateDynamicRules({
        removeRuleIds: [tabId]
      }).catch(() => {});
    }
  }
});

async function launchParallelFarmBatch(batchIndex = 0) {
  try {
    const storageData = await chrome.storage.local.get(['multi_profiles', 'ctb_saved_prompts', 'ctb_max_credits_limit']);
    const multiProfiles = storageData.multi_profiles || {};
    const maxCredits = parseInt(storageData?.ctb_max_credits_limit, 10) === 10 ? 10 : 6;
    const profileEntries = Object.entries(multiProfiles).map(([name, data]) => ({
      name,
      ...data
    }));

    if (profileEntries.length === 0) {
      return { ok: false, error: 'No saved accounts found. Please upload or add accounts in the Accounts tab.' };
    }

    const totalAccounts = profileEntries.length;
    const totalBatches = Math.max(1, Math.ceil(totalAccounts / farmState.accountsPerBatch));
    const safeBatchIdx = Math.max(0, batchIndex % totalBatches);

    farmState.currentBatchIndex = safeBatchIdx;
    farmState.active = true;

    // Slice 10 accounts for this batch
    const startAccIdx = safeBatchIdx * farmState.accountsPerBatch;
    const batchAccounts = [];
    for (let i = 0; i < farmState.accountsPerBatch; i++) {
      const idx = (startAccIdx + i) % totalAccounts;
      batchAccounts.push(profileEntries[idx]);
    }

    // Slice 10 prompts for this batch
    const savedPrompts = Array.isArray(storageData.ctb_saved_prompts) ? storageData.ctb_saved_prompts : [];
    const startPromptIdx = safeBatchIdx * (farmState.accountsPerBatch * farmState.slotsPerAccount);

    // Clear old farm tabs if any
    farmState.tabPromptMap.clear();
    farmState.tabAccountMap.clear();
    const oldTabs = [...farmState.farmTabs];
    farmState.farmTabs = [];

    for (const oldId of oldTabs) {
      try {
        await chrome.tabs.remove(oldId);
      } catch (e) {}
    }

    // Spawn 10 Tabs (1 tab per account across 10 accounts)
    const newTabIds = [];
    let promptCounter = 0;

    for (let aIdx = 0; aIdx < batchAccounts.length; aIdx++) {
      const account = batchAccounts[aIdx];
      for (let slot = 0; slot < farmState.slotsPerAccount; slot++) {
        const globalPromptIdx = startPromptIdx + promptCounter;
        const promptObj = savedPrompts[globalPromptIdx] || savedPrompts[globalPromptIdx % Math.max(1, savedPrompts.length)] || { prompt: '', title: '' };

        // 1. Create tab in blank state (0ms, no network traffic to dola.com yet)
        const tab = await chrome.tabs.create({
          url: 'about:blank',
          active: (aIdx === 0 && slot === 0)
        });

        newTabIds.push(tab.id);
        farmState.farmTabs.push(tab.id);

        // 2. Apply per-tab declarativeNetRequest container rule BEFORE navigating
        await applyTabSessionRule(tab.id, account);

        // 3. Navigate tab to Dola with account rule already 100% active (loads isolated account on first try)
        await chrome.tabs.update(tab.id, { url: 'https://www.dola.com/chat' });

        // Map assigned prompt for this tab slot
        farmState.tabPromptMap.set(tab.id, {
          promptText: promptObj.prompt || '',
          promptNumber: globalPromptIdx + 1,
          promptTitle: promptObj.title || (`Prompt #${String(globalPromptIdx + 1).padStart(2, '0')}`),
          accountName: account.name,
          slotNumber: slot + 1,
          batchIndex: safeBatchIdx,
          maxCredits: maxCredits
        });
        farmState.tabAccountMap.set(tab.id, account);

        promptCounter++;
      }
    }

    console.log(`[ChannaTheBrand Farm] 🚀 Successfully spawned ${newTabIds.length} tabs for Batch #${safeBatchIdx + 1} (${batchAccounts.map(a => a.name).join(', ')})`);

    return {
      ok: true,
      batchIndex: safeBatchIdx,
      totalBatches,
      accountsCount: totalAccounts,
      promptsCount: savedPrompts.length,
      tabsCount: newTabIds.length,
      accountsUsed: batchAccounts.map(a => a.name)
    };
  } catch (err) {
    console.error('[ChannaTheBrand Farm] Launch failed:', err);
    return { ok: false, error: err.message || String(err) };
  }
}

async function switchParallelFarmBatch(targetBatchIndex = null) {
  try {
    const storageData = await chrome.storage.local.get(['multi_profiles', 'ctb_saved_prompts']);
    const multiProfiles = storageData.multi_profiles || {};
    const profileEntries = Object.entries(multiProfiles).map(([name, data]) => ({
      name,
      ...data
    }));

    if (profileEntries.length === 0) {
      return { ok: false, error: 'No saved accounts found.' };
    }

    const totalAccounts = profileEntries.length;
    const totalBatches = Math.max(1, Math.ceil(totalAccounts / farmState.accountsPerBatch));
    
    let nextBatchIdx;
    if (typeof targetBatchIndex === 'number') {
      nextBatchIdx = targetBatchIndex % totalBatches;
    } else {
      nextBatchIdx = (farmState.currentBatchIndex + 1) % totalBatches;
    }

    return await launchParallelFarmBatch(nextBatchIdx);
  } catch (err) {
    console.error('[ChannaTheBrand Farm] Switch failed:', err);
    return { ok: false, error: err.message || String(err) };
  }
}

async function closeAllFarmTabs() {
  const tabsToClose = [...farmState.farmTabs];
  farmState.farmTabs = [];
  farmState.tabPromptMap.clear();
  farmState.tabAccountMap.clear();
  farmState.active = false;

  for (const tid of tabsToClose) {
    try {
      await chrome.tabs.remove(tid);
    } catch (e) {}
  }
  return { ok: true, closedCount: tabsToClose.length };
}

function getFarmAssignedPrompt(tabId) {
  if (!tabId || !farmState.tabPromptMap.has(tabId)) {
    return { hasAssignedPrompt: false };
  }
  const info = farmState.tabPromptMap.get(tabId);
  return {
    hasAssignedPrompt: true,
    ...info
  };
}

function getFarmStatus() {
  return {
    ok: true,
    active: farmState.active,
    currentBatchIndex: farmState.currentBatchIndex,
    openTabsCount: farmState.farmTabs.length
  };
}

chrome.runtime.onInstalled.addListener(async () => {
  if (chrome.sidePanel && chrome.sidePanel.setPanelBehavior) {
    chrome.sidePanel.setPanelBehavior({ openPanelOnActionClick: true }).catch(() => {});
  }
  await zdolaLoadState();
  zdolaUpdateBadge();
  zdolaAutoInjectIntoExistingTabs();
});

